style:
/* 紫锋 —— 紫色顶带 + 双箭头模块标题 + 点线分隔 */

.tw-zifeng.resume-paper {
  background: #ffffff;
  color: #2a2d3a;
}

/* 顶部通栏：斜切光带铺满页边 */
.tw-zifeng.resume-paper .paper-flow {
  position: relative;
}

.tw-zifeng.resume-paper .paper-flow::before {
  content: "";
  position: absolute;
  top: -15mm;
  left: -15mm;
  right: -15mm;
  height: 11.5mm;
  background:
    linear-gradient(100deg, rgba(255, 255, 255, 0.22) 0 9%, rgba(255, 255, 255, 0) 9% 100%),
    linear-gradient(102deg, #6a4fe0 0%, #5b3fd6 52%, #4326b8 100%);
  print-color-adjust: exact;
}

/* 页眉：姓名前双角标，求职意向做成实心徽章 */
.tw-zifeng.resume-paper .paper-header {
  margin-bottom: 4mm;
  padding-bottom: 0;
  border: none;
}

.tw-zifeng.resume-paper .paper-header--photo {
  align-items: center;
  gap: 8mm;
}

.tw-zifeng.resume-paper .paper-header__main {
  flex: 1 1 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 6mm;
  row-gap: 2mm;
  min-width: 0;
}

.tw-zifeng.resume-paper .paper-name-row {
  flex: 0 0 auto;
  align-items: baseline;
  gap: 0;
}

.tw-zifeng.resume-paper .paper-name-row::before {
  content: "\00bb";
  margin-right: 2.6mm;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2.15);
  font-weight: 700;
  line-height: 1;
}

.tw-zifeng.resume-paper .paper-name {
  color: #1d2030;
  font-size: calc(var(--paper-base-size) * 2.15);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.tw-zifeng.resume-paper .paper-identity {
  padding: 0;
  border: none;
  border-radius: 0;
  color: #6f7488;
  font-size: calc(var(--paper-base-size) * 0.9);
}

.tw-zifeng.resume-paper .paper-role {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 1.1mm 3.2mm;
  border-radius: 1mm;
  background: var(--paper-accent);
  color: #ffffff;
  font-size: calc(var(--paper-base-size) * 0.95);
  font-weight: 600;
  letter-spacing: 0.02em;
  print-color-adjust: exact;
}

.tw-zifeng.resume-paper .paper-role::before {
  content: "意向岗位：";
  color: rgba(255, 255, 255, 0.74);
  font-weight: 400;
}

/* 基本信息：两列网格，标签灰、值深 */
.tw-zifeng.resume-paper .paper-contacts--labeled {
  flex: 1 0 100%;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 10mm;
  margin-top: 4.6mm;
  padding: 0;
  border: none;
  color: #333648;
  font-size: calc(var(--paper-base-size) * 0.9);
}

.tw-zifeng.resume-paper .paper-contact {
  display: flex;
  gap: 1.6mm;
  min-width: 0;
}

.tw-zifeng.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-zifeng.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: #7b8096;
}

.tw-zifeng.resume-paper .paper-photo {
  order: 2;
  width: 25mm;
  height: 33mm;
  border: none;
  border-radius: 1.4mm;
  object-fit: cover;
}

/* 模块标题：双箭头图标 + 主题色标题 + 点线收尾 */
.tw-zifeng.resume-paper .paper-style-icon .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.6mm;
  margin: 0 0 2.8mm;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.12);
  font-weight: 700;
  letter-spacing: 0.03em;
}

.tw-zifeng.resume-paper .paper-style-icon .paper-section__icon {
  position: relative;
  display: block;
  flex: 0 0 auto;
  width: 6.2mm;
  height: 5mm;
  border: none;
  border-radius: 0;
  background: transparent;
}

.tw-zifeng.resume-paper .paper-style-icon .paper-section__icon svg {
  display: none;
}

.tw-zifeng.resume-paper .paper-style-icon .paper-section__icon::before,
.tw-zifeng.resume-paper .paper-style-icon .paper-section__icon::after {
  content: "";
  position: absolute;
  top: 0;
  width: 2.4mm;
  height: 5mm;
  background: var(--paper-accent);
  clip-path: polygon(0 0, 52% 50%, 0 100%, 46% 100%, 100% 50%, 46% 0);
  print-color-adjust: exact;
}

.tw-zifeng.resume-paper .paper-style-icon .paper-section__icon::before {
  left: 0;
}

.tw-zifeng.resume-paper .paper-style-icon .paper-section__icon::after {
  left: 2.9mm;
}

.tw-zifeng.resume-paper .paper-style-icon .paper-section__title::after {
  content: "";
  flex: 1;
  align-self: center;
  border-top: 1px dotted #cfc9e6;
}

/* 条目：日期靠右，专业 / 职位紧跟在标题下方 */
.tw-zifeng.resume-paper .paper-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 4mm;
  row-gap: 1mm;
}

.tw-zifeng.resume-paper .paper-item > * {
  flex: 1 0 100%;
}

.tw-zifeng.resume-paper .paper-item > .paper-item-head {
  flex: 1 1 100%;
}

.tw-zifeng.resume-paper .paper-item-period {
  color: #6f7488;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

.tw-zifeng.resume-paper .paper-item-title {
  color: #1d2030;
  font-weight: 700;
}

.tw-zifeng.resume-paper .paper-item > .paper-item-sub {
  flex: 1 0 100%;
  margin-top: 0.4mm;
}

.tw-zifeng.resume-paper .paper-item-sub span + span::before {
  content: " | ";
  margin-right: 0;
  color: #c9c9d8;
}

/* 求职意向：标签 + 值连成一行流 */
.tw-zifeng.resume-paper .is-job_intention .paper-section__title {
  display: flex;
}

.tw-zifeng.resume-paper .is-job_intention .paper-item {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 8mm;
}

.tw-zifeng.resume-paper .is-job_intention .paper-item-head {
  display: flex;
  flex: 0 0 auto;
  gap: 8mm;
  justify-content: flex-start;
}

.tw-zifeng.resume-paper .is-job_intention .paper-item-title::before {
  content: "意向岗位：";
  color: #7b8096;
  font-weight: 400;
}

.tw-zifeng.resume-paper .is-job_intention .paper-item-period {
  order: 0;
}

.tw-zifeng.resume-paper .is-job_intention .paper-item-period::before {
  content: "意向城市：";
  color: #7b8096;
  font-weight: 400;
}

.tw-zifeng.resume-paper .is-job_intention .paper-item-sub {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 8mm;
  margin-left: 0;
  color: #333648;
}

.tw-zifeng.resume-paper .is-job_intention .paper-item-sub span + span::before {
  content: "";
  margin-right: 0;
}

/* 正文细节 */
.tw-zifeng.resume-paper .paper-note {
  color: #5f6478;
}

.tw-zifeng.resume-paper .paper-note__tag {
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: #5b3fd6;
  font-weight: 600;
}

.tw-zifeng.resume-paper .paper-meta-line {
  color: #6f7488;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-zifeng.resume-paper .paper-item-tag {
  color: #5b3fd6;
}

.tw-zifeng.resume-paper .paper-rich {
  color: #3a3d4e;
}

.tw-zifeng.resume-paper .paper-rich li {
  margin: 0.4mm 0;
}

.tw-zifeng.resume-paper .paper-rich li::marker {
  color: var(--paper-accent);
}

.tw-zifeng.resume-paper .paper-skill {
  border-bottom: 1px solid #eceaf5;
}

.tw-zifeng.resume-paper .paper-skill__name {
  color: #2a2d3a;
  font-weight: 600;
}

.tw-zifeng.resume-paper .paper-skill__dots {
  display: none;
}

.tw-zifeng.resume-paper .paper-skill__level {
  display: inline;
  color: #6f7488;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-zifeng.resume-paper .paper-footer {
  margin-top: 8mm;
  padding-top: 2.4mm;
  border-top: 1px dotted #dad6ea;
  color: #9a9db0;
}
